-- Generated by scripts/sync-feature-registry.ts — do not edit by hand.
-- Registry sync: manifests -> feature_flags, permissions, role_permissions.

create table if not exists public.feature_registry (
  key text primary key,
  name text not null,
  description text not null,
  icon text not null,
  nav_path text,
  nav_order int,
  nav_permission text,
  flag_key text not null,
  settings_path text,
  permissions jsonb not null default '[]'::jsonb,
  analytics jsonb not null default '{}'::jsonb,
  activity_actions text[] not null default '{}',
  usage_meters jsonb not null default '[]'::jsonb,
  ai_tools jsonb not null default '[]'::jsonb,
  data_tables text[] not null default '{}',
  synced_at timestamptz not null default now()
);
alter table public.feature_registry add column if not exists ai_tools jsonb not null default '[]'::jsonb;
grant select on public.feature_registry to authenticated;
grant all on public.feature_registry to service_role;
alter table public.feature_registry enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='feature_registry' and policyname='feature_registry_select_all') then
    create policy "feature_registry_select_all" on public.feature_registry for select to authenticated using (true);
  end if;
end $$;

alter table public.permissions drop constraint if exists permissions_category_check;

